CREATE TABLE product_categories(id BIGSERIAL PRIMARY KEY,name VARCHAR(80) UNIQUE NOT NULL); CREATE TABLE products(id BIGSERIAL PRIMARY KEY,name VARCHAR(160) NOT NULL,category VARCHAR(80),price NUMERIC(12,2) NOT NULL CHECK(price>=0),unit VARCHAR(20) NOT NULL DEFAULT 'kg',active BOOLEAN NOT NULL DEFAULT true); CREATE TABLE product_images(id BIGSERIAL PRIMARY KEY,product_id BIGINT REFERENCES products(id) ON DELETE CASCADE,image_url TEXT NOT NULL,is_primary BOOLEAN DEFAULT false);